const CUTOFF = new Date(); // cierre del día: ahora (23:55)
const CONNECTED = ['online', 'busy']; // busy cuenta como conectado
const TZ = 'America/Mexico_City';

// Formatear timestamps en hora CDMX, legible para el sheet
const fmtCDMX = (d) =>
  DateTime.fromJSDate(d).setZone(TZ).toFormat('yyyy-MM-dd HH:mm:ss');

const events = $input.all()
  .map(i => i.json)
  .filter(e => e.agent_id !== undefined && e.agent_id !== '')
  .sort((a, b) => new Date(a.changed_at) - new Date(b.changed_at));

// Agrupar por agente
const byAgent = {};
for (const e of events) {
  const id = String(e.agent_id);
  if (!byAgent[id]) byAgent[id] = { name: e.name, events: [] };
  byAgent[id].events.push(e);
}

const fecha = DateTime.fromJSDate(CUTOFF).setZone(TZ).toFormat('yyyy-MM-dd');
const out = [];

for (const [agentId, data] of Object.entries(byAgent)) {
  let sessionStart = null;
  let totalMs = 0;
  let numSesiones = 0;
  let primera = null;
  let ultima = null;

  for (const e of data.events) {
    const t = new Date(e.changed_at);
    const isConnected = CONNECTED.includes(e.to_status);

    if (isConnected && !sessionStart) {
      sessionStart = t;
      if (!primera) primera = t;
    } else if (!isConnected && sessionStart) {
      totalMs += t - sessionStart;
      numSesiones++;
      ultima = t;
      sessionStart = null;
    }
  }

  // Sesión aún abierta al cierre del día
  let sigueConectado = false;
  if (sessionStart) {
    totalMs += CUTOFF - sessionStart;
    numSesiones++;
    sigueConectado = true;
  }

  out.push({
    json: {
      id_agente: `${fecha}_${agentId}`,
      fecha,
      agent_id: Number(agentId),
      name: data.name,
      horas_conectado: Math.round((totalMs / 3600000) * 100) / 100,
      num_sesiones: numSesiones,
      primera_conexion: primera ? fmtCDMX(primera) : '',
      ultima_desconexion: sigueConectado ? 'sigue conectado' : (ultima ? fmtCDMX(ultima) : ''),
    }
  });
}

return out;

// Re-sembrar evento de apertura para agentes que siguen conectados
const CONNECTED = ['online', 'busy'];
const now = DateTime.now().setZone('America/Mexico_City').toISO();

// Leemos el resumen calculado: quien quedó "sigue conectado"
const abiertos = $('Calcular horas').all()
  .map(i => i.json)
  .filter(r => r.ultima_desconexion === 'sigue conectado');

return abiertos.map(r => ({
  json: {
    agent_id: r.agent_id,
    name: r.name,
    from_status: null,
    to_status: 'online',
    changed_at: now,
  }
}));

const rows = $input.all().map(i => i.json);

if (rows.length === 0) {
  return [{ json: { fecha: $now.setZone('America/Mexico_City').toFormat('yyyy-MM-dd'),
    sin_datos: true } }];
}

const num = v => Number(v) || 0;

// Totales del día
let totalTokens = 0, totalPrompt = 0, totalCompletion = 0, totalCost = 0;
const conversaciones = new Set();
const mensajes = new Set();

// Desglose por workflow
const porWorkflow = {};

for (const r of rows) {
  totalTokens += num(r.totalTokens);
  totalPrompt += num(r.promptTokens);
  totalCompletion += num(r.completionTokens);
  totalCost += num(r.cost_usd);

  if (r.conversation_id) conversaciones.add(String(r.conversation_id));
  if (r.message_key) mensajes.add(String(r.message_key));

  const wf = r.workflow_name || 'desconocido';
  if (!porWorkflow[wf]) porWorkflow[wf] = { tokens: 0, cost: 0 };
  porWorkflow[wf].tokens += num(r.totalTokens);
  porWorkflow[wf].cost += num(r.cost_usd);
}

const nConv = conversaciones.size || 1;  // evitar división entre 0
const nMsg = mensajes.size || 1;
const r6 = x => Math.round(x * 1e6) / 1e6;
const r2 = x => Math.round(x * 100) / 100;

const fecha = rows[0].fecha || $now.setZone('America/Mexico_City').toFormat('yyyy-MM-dd');

return [{
  json: {
    fecha,
    conversaciones: conversaciones.size,
    mensajes: mensajes.size,
    total_tokens: totalTokens,
    prompt_tokens: totalPrompt,
    completion_tokens: totalCompletion,
    costo_total_usd: r6(totalCost),
    // Las dos métricas que buscas:
    costo_por_conversacion_usd: r6(totalCost / nConv),
    costo_por_mensaje_usd: r6(totalCost / nMsg),
    tokens_por_conversacion: r2(totalTokens / nConv),
    tokens_por_mensaje: r2(totalTokens / nMsg),
    // Desglose por agente
    tokens_orquestador: porWorkflow['agente_orquestador']?.tokens || 0,
    tokens_event: porWorkflow['event']?.tokens || 0,
    costo_orquestador_usd: r6(porWorkflow['agente_orquestador']?.cost || 0),
    costo_event_usd: r6(porWorkflow['event']?.cost || 0)
  }
}];

const ayer = DateTime.now()
  .setZone('America/Mexico_City')
  .minus({ days: 1 })
  .toFormat('yyyy-MM-dd');

const rows = $input.all();

let total = 0;
const porMotivo = {};
const convsUnicas = new Set();

for (const item of rows) {
  // Normaliza keys: quita espacios finales en headers (el clásico "fecha ")
  const row = {};
  for (const [k, v] of Object.entries(item.json)) {
    row[k.trim()] = typeof v === 'string' ? v.trim() : v;
  }

  // Normaliza la fecha a YYYY-MM-DD por si viene con hora o formato raro
  const fechaRaw = String(row.fecha ?? '');
  const fecha = fechaRaw.slice(0, 10);

  if (fecha !== ayer) continue;

  total++;
  if (row.conversation_id) convsUnicas.add(String(row.conversation_id));

  const motivo = (row.motivo || 'sin_motivo').toString().toLowerCase();
  porMotivo[motivo] = (porMotivo[motivo] || 0) + 1;
}

return [{
  json: {
    fecha: ayer,
    total_ignorados: total,
    conversaciones_unicas: convsUnicas.size,
    motivos: JSON.stringify(porMotivo)
  }
}];

const ayer = DateTime.now()
  .setZone('America/Mexico_City')
  .minus({ days: 1 })
  .toFormat('yyyy-MM-dd');

const rows = $input.all();

let total = 0;
const porAgente = {};
const convsUnicas = new Set();

for (const item of rows) {
  const row = {};
  for (const [k, v] of Object.entries(item.json)) {
    row[k.trim()] = typeof v === 'string' ? v.trim() : v;
  }

  // 1) filtrar por fecha
  const fecha = String(row.fecha ?? '').slice(0, 10);
  if (fecha !== ayer) continue;

  // 2) filtrar por tipo de cierre — SOLO escalaciones a humano
  if (String(row.tipo_cierre ?? '').trim() !== 'AGENTE') continue;

  total++;
  if (row.conversation_id) convsUnicas.add(String(row.conversation_id));

  const agente = String(row.agente_destino ?? 'desconocido');
  porAgente[agente] = (porAgente[agente] || 0) + 1;
}

return [{
  json: {
    fecha: ayer,
    total_escalaciones: total,
    conversaciones_unicas: convsUnicas.size,
    por_agente: JSON.stringify(porAgente)
  }
}];

/* ============================================================
   n8n Code node — "Jornadas por agente" (bloques de conexión)
   Entrada : filas del sheet `eventos`
             (agent_id, name, from_status, to_status, changed_at)
             changed_at ya viene en CDMX con offset -06:00.
   Salida  : 1 item por (agente, día) con los BLOQUES de conexión
             reconstruidos, horas conectadas y flags.
   Notas   : DateTime es global en n8n (no usar require('luxon')).
   ============================================================ */

const TZ            = 'America/Mexico_City';
const WINDOW_DAYS   = 30;                  // "registro de días anteriores"
const GAP_MERGE_MIN = 15;                  // <<< TUNEA AQUÍ:
                                           //  5  -> ves descansos cortos
                                           //  30 -> solo turnos (7-9 / 15-21)
const CONNECTED     = ['online', 'busy'];  // ambos = conectado

const now   = DateTime.now().setZone(TZ);
const desde = now.startOf('day').minus({ days: WINDOW_DAYS }).toISODate();

// --- eventos agrupados por agente ---------------------------------
const evByAgent = {};
for (const it of $input.all()) {
  const r = it.json;
  const t = DateTime.fromISO(String(r.changed_at)).setZone(TZ);
  if (!t.isValid) continue;
  const aid = String(r.agent_id).trim();
  (evByAgent[aid] ||= { name: String(r.name || '').trim(), evs: [] })
    .evs.push({ t, to: r.to_status });
}

const ensureDay = (dias, d) =>
  (dias[d] ||= { bloques: [], horas_conectado: 0, cruza_medianoche: false });

const out = [];
for (const [aid, { name, evs }] of Object.entries(evByAgent)) {
  evs.sort((a, b) => a.t.toMillis() - b.t.toMillis());

  // 1) intervalos CRUDOS conectados (offline cierra; online<->busy no)
  const raw = [];
  let op = null;
  for (const e of evs) {
    if (CONNECTED.includes(e.to) && !op) op = e.t;
    else if (e.to === 'offline' && op) { raw.push([op, e.t]); op = null; }
  }
  if (op) raw.push([op, null]);            // sigue conectado

  // 2) bloques FUSIONADOS (solo para la línea de tiempo)
  const merged = [];
  for (const iv of raw) {
    const last = merged[merged.length - 1];
    if (last && iv[0] && last[1] &&
        iv[0].diff(last[1], 'minutes').minutes <= GAP_MERGE_MIN) last[1] = iv[1];
    else merged.push([iv[0], iv[1]]);
  }

  const dias = {};

  // 3a) horas_conectado desde el CRUDO (independiente del gap) + corte por día
  for (const [a, b] of raw) {
    const bb = b || now;
    let cur = a;
    while (cur.toISODate() < bb.toISODate()) {
      const nd = cur.plus({ days: 1 }).startOf('day');
      const dd = ensureDay(dias, cur.toISODate());
      dd.horas_conectado += nd.diff(cur, 'hours').hours;
      dd.cruza_medianoche = true;
      cur = nd;
    }
    ensureDay(dias, cur.toISODate()).horas_conectado += bb.diff(cur, 'hours').hours;
  }

  // 3b) bloques (merged) por día para el timeline
  for (const [a, b] of merged) {
    const curso = b === null;
    const bb = b || now;
    let cur = a;
    while (cur.toISODate() < bb.toISODate()) {
      const nd = cur.plus({ days: 1 }).startOf('day');
      // termina en el límite del día -> "24:00" (no "00:00") y marca continuación
      ensureDay(dias, cur.toISODate()).bloques.push(
        { inicio: cur.toFormat('HH:mm'), fin: '24:00', en_curso: false, continua: true });
      cur = nd;
    }
    ensureDay(dias, cur.toISODate()).bloques.push(
      { inicio: cur.toFormat('HH:mm'), fin: curso ? null : bb.toFormat('HH:mm'), en_curso: curso });
  }

  // 4) emitir dentro de la ventana
  for (const [d, v] of Object.entries(dias)) {
    if (d < desde) continue;
    out.push({ json: {
      agent_id: aid, name, dia: d,
      horas_conectado: Math.round(v.horas_conectado * 100) / 100,
      n_bloques: v.bloques.length,
      bloques: v.bloques,
      en_curso: v.bloques.some(x => x.en_curso),
      cruza_medianoche: v.cruza_medianoche,
    }});
  }
}

// día desc, luego nombre
out.sort((a, b) =>
  a.json.dia < b.json.dia ? 1 : a.json.dia > b.json.dia ? -1 :
  a.json.name.localeCompare(b.json.name));
return out;


/* ============================================================
   Chart.js — línea de tiempo de UN día (barras horizontales flotantes).
   `filas` = items de este Code node filtrados a un `dia`.
   ============================================================
const toMin = hhmm => { const [h,m]=hhmm.split(':').map(Number); return h*60+m; };
const filas = data.filter(r => r.dia === diaSeleccionado)
                  .sort((a,b)=>a.name.localeCompare(b.name));
const labels = filas.map(r => r.name);

// un dataset por "slot" de bloque (para dibujar varios bloques por agente)
const maxB = Math.max(1, ...filas.map(r => r.bloques.length));
const datasets = Array.from({length:maxB}, (_,i)=>({
  label: `bloque ${i+1}`,
  data: filas.map(r => {
    const b = r.bloques[i];
    if (!b) return null;
    const ini = toMin(b.inicio);
    let fin = b.en_curso ? toMin(new Date().toTimeString().slice(0,5)) : toMin(b.fin);
    fin = Math.max(fin, ini + 1);       // nunca una barra invertida
    return [ini, fin];                  // barra flotante [inicio, fin]
  }),
  borderWidth: 1,
}));

new Chart(ctx, {
  type: 'bar',
  data: { labels, datasets },
  options: {
    indexAxis: 'y',
    plugins: { title:{display:true,text:`Jornadas — ${diaSeleccionado}`}, legend:{display:false} },
    scales: {
      x: { min:0, max:1440, title:{display:true,text:'Hora (CDMX)'},
           ticks:{ stepSize:60, callback:v=>String(v/60).padStart(2,'0')+':00' } },
      y: { stacked:false }
    }
  }
});
